// 沿用已验证的静态 FBX 轴向和共享材质，仅操作模型展示场景。
if (EditorApplication.isPlaying) throw new System.InvalidOperationException("请先退出 Play。");
var scene = UnityEngine.SceneManagement.SceneManager.GetActiveScene();
if (scene.path != "Assets/DynamicAsset/MapLowPoly/MapLowPolyPreview.unity" || scene.isDirty) throw new System.InvalidOperationException("展示场景不符合预期或存在未保存修改。");
var root = scene.GetRootGameObjects().Single(x => x.name == "MapLowPoly_展示");
if (root.transform.Find("Building_Castle") != null) throw new System.InvalidOperationException("城堡展示已存在。");
var modelPath = "Assets/DynamicAsset/MapLowPoly/Models/Building_Castle.fbx";
var importer = AssetImporter.GetAtPath(modelPath) as ModelImporter;
if (importer == null) throw new System.InvalidOperationException("缺少城堡导入器。");
var names = new[] {"RockDark", "Stone", "City", "RockLight", "Window", "PlasterShade", "Gable", "RoofShade", "Roof", "Timber", "TimberLight"};
var materials = names.Select(x => AssetDatabase.LoadAssetAtPath<Material>("Assets/DynamicAsset/MapLowPoly/Materials/M_MapLP_" + x + ".mat")).ToArray();
if (materials.Any(x => x == null)) throw new System.InvalidOperationException("缺少共享材质。");
importer.globalScale = 1f;
importer.useFileScale = true;
importer.bakeAxisConversion = true;
importer.importNormals = ModelImporterNormals.Import;
importer.importTangents = ModelImporterTangents.None;
importer.importAnimation = false;
importer.animationType = ModelImporterAnimationType.None;
importer.isReadable = false;
importer.materialImportMode = ModelImporterMaterialImportMode.ImportStandard;
importer.materialLocation = ModelImporterMaterialLocation.InPrefab;
foreach (var material in materials) importer.AddRemap(new AssetImporter.SourceAssetIdentifier(typeof(Material), material.name), material);
importer.SaveAndReimport();
var asset = AssetDatabase.LoadAssetAtPath<GameObject>(modelPath);
var castle = (GameObject)PrefabUtility.InstantiatePrefab(asset, scene);
castle.name = "Building_Castle";
castle.transform.SetParent(root.transform, false);
castle.transform.localPosition = new Vector3(9f, 0f, -.7f);
castle.transform.localRotation = Quaternion.identity;
castle.transform.localScale = Vector3.one;
foreach (var item in castle.GetComponentsInChildren<Transform>(true)) item.gameObject.layer = 31;
var plotAsset = AssetDatabase.LoadAssetAtPath<GameObject>("Assets/DynamicAsset/MapLowPoly/Models/CityPlot7.fbx");
var plot = (GameObject)PrefabUtility.InstantiatePrefab(plotAsset, scene);
plot.name = "CityPlot7_Castle";
plot.transform.SetParent(root.transform, false);
plot.transform.localPosition = castle.transform.localPosition;
plot.transform.localRotation = Quaternion.identity;
plot.transform.localScale = new Vector3(1f, .22f, 1f);
foreach (var item in plot.GetComponentsInChildren<Transform>(true)) item.gameObject.layer = 31;
// 单独保存城堡机位，默认关闭，方便后续查看单体；主机位展示全套资源。
var cameraObject = new GameObject("Castle_PreviewCamera");
UnityEngine.SceneManagement.SceneManager.MoveGameObjectToScene(cameraObject, scene);
var camera = cameraObject.AddComponent<Camera>();
camera.enabled = false;
camera.orthographic = true;
camera.orthographicSize = 3.35f;
camera.nearClipPlane = .1f;
camera.farClipPlane = 100f;
camera.cullingMask = 1 << 31;
camera.clearFlags = CameraClearFlags.SolidColor;
camera.backgroundColor = new Color(.78f, .8f, .78f, 1f);
camera.transform.position = new Vector3(15f, 7.5f, 9.3f);
camera.transform.LookAt(new Vector3(9f, 1.35f, -.7f));
var overview = scene.GetRootGameObjects().Single(x => x.name == "MapLowPoly_PreviewCamera").GetComponent<Camera>();
overview.orthographicSize = 6.9f;
overview.transform.position = new Vector3(10.8f, 14f, 15.4f);
overview.transform.LookAt(new Vector3(2.3f, .5f, .9f));
EditorUtility.SetDirty(overview);
UnityEditor.SceneManagement.EditorSceneManager.MarkSceneDirty(scene);
if (!UnityEditor.SceneManagement.EditorSceneManager.SaveScene(scene)) throw new System.InvalidOperationException("展示场景保存失败。");
Selection.activeGameObject = castle;
if (SceneView.lastActiveSceneView != null) SceneView.lastActiveSceneView.FrameSelected();
var mesh = asset.GetComponent<MeshFilter>().sharedMesh;
var bounds = asset.GetComponent<MeshRenderer>().bounds;
return new { model = modelPath, scene = scene.path, castleInstanceId = castle.GetInstanceID(), plotInstanceId = plot.GetInstanceID(), cameraInstanceId = cameraObject.GetInstanceID(), triangles = Enumerable.Range(0, mesh.subMeshCount).Sum(i => (long)mesh.GetIndexCount(i) / 3), size = new [] {bounds.size.x, bounds.size.y, bounds.size.z}, rotation = new [] {asset.transform.localEulerAngles.x, asset.transform.localEulerAngles.y, asset.transform.localEulerAngles.z}, materialPaths = asset.GetComponent<MeshRenderer>().sharedMaterials.Select(x => AssetDatabase.GetAssetPath(x)).ToArray() };
